  (2001, 2, 11, null, 'Bauordnungsrecht entschlacken, Gebäudetyp E, befristete Ausnahmen vom Planungsrecht in angespannten Wohnungsmärkten', '{201,203,205}', null, 2, 2, null, 'Senkt Baukosten und beschleunigt Planung; Bauordnungen sind Ländersache, die Wirkung hängt daher auch von den Ländern ab.', 'https://www.cdu.de/app/uploads/2025/01/km_btw_2025_wahlprogramm_langfassung_ansicht.pdf#page=73', null, 'gemischt', '2026-09-30', false, true, null, null),
  (2002, 2, 11, null, 'Mehr Bauland: Brach- und Konversionsflächen sowie bundeseigene Grundstücke für den Wohnungsbau nutzen', '{201,205}', null, 2, 2, null, 'Mehr verfügbare Flächen erleichtern Neubau in Wachstumsregionen; Umfang und Tempo hängen von Kommunen und Ländern ab.', 'https://www.cdu.de/app/uploads/2025/01/km_btw_2025_wahlprogramm_langfassung_ansicht.pdf#page=73', null, 'gemischt', '2026-09-30', false, true, null, null),
  (2003, 2, 11, null, 'Keine neuen kostentreibenden Standards (Baukostenmoratorium), Genehmigungsverfahren digitalisieren und beschleunigen', '{203}', 6641, 2, 3, null, 'Verhindert weitere Kostensteigerungen durch Vorschriften und verkürzt Verfahren; bereits gestiegene Material-, Lohn- und Zinskosten bleiben. Wie viel Standards an den Baukosten ausmachen, ist umstritten.', 'https://www.cdu.de/app/uploads/2025/01/km_btw_2025_wahlprogramm_langfassung_ansicht.pdf#page=73', null, 'gemischt', '2026-09-27', false, true, null, null),
  (2004, 2, 11, null, 'Höhere befristete Sonderabschreibung und degressive Abschreibung für bezahlbaren Mietwohnungsbau in angespannten Märkten', '{201}', 6640, 2, 2, null, 'Steuerliche Anreize können Neubau anstoßen; kostet Steuereinnahmen, und ob die Wohnungen günstig vermietet werden, ist nicht gesichert. Frühere Sonderabschreibungen wirkten vor allem bei ohnehin geplanten Projekten.', 'https://www.cdu.de/app/uploads/2025/01/km_btw_2025_wahlprogramm_langfassung_ansicht.pdf#page=73', null, 'gemischt', '2026-09-27', false, true, null, null),
  (2005, 2, 11, null, 'Sozialen Wohnungsbau solide fördern und Wohngeld regelmäßig anpassen', '{201,202,206}', null, 1, 3, null, 'Hält bestehende Instrumente aufrecht, ohne Umfang oder Ausbau zu beziffern; Wohngeld entlastet, schafft aber keine Wohnungen.', 'https://www.cdu.de/app/uploads/2025/01/km_btw_2025_wahlprogramm_langfassung_ansicht.pdf#page=73', null, 'belegt', '2026-09-27', false, true, null, null),
  (2006, 2, 11, null, 'Steuerliche Nachteile für Vermieter abschaffen, die weniger als die ortsübliche Vergleichsmiete verlangen', '{202}', null, 1, 3, null, 'Setzt einen kleinen Anreiz für günstige Mieten, vor allem bei privaten Vermietern; die Wirkung auf das Mietniveau ist begrenzt.', 'https://www.cdu.de/app/uploads/2025/01/km_btw_2025_wahlprogramm_langfassung_ansicht.pdf#page=73', null, 'offen', '2026-09-27', false, true, null, null),
  (2011, 2, 12, null, 'Mietpreisbremse unbefristet verlängern, auf Wohnungen bis Baujahr 2019 ausweiten und Umgehung über möblierte oder befristete Angebote verhindern', '{202}', null, 2, 2, '{"mieter":{"wert":1,"begruendung":"Begrenzt die Miete bei Neuvermietung unmittelbar."},"eigentuemer":{"wert":-1,"begruendung":"Begrenzt mögliche Mieteinnahmen bei Neuvermietung."}}'::jsonb, 'Dämpft Mieten bei Neuvermietung in angespannten Märkten; schafft keine neuen Wohnungen. Eine unbefristete Geltung ist verfassungsrechtlich weniger abgesichert als die befristete.', 'https://www.spd.de/fileadmin/Dokumente/Beschluesse/Programm/2025_SPD_Regierungsprogramm.pdf#page=20', null, 'gemischt', '2026-09-27', false, true, null, null),
  (2012, 2, 12, null, 'Mieterhöhungen im Bestand in angespannten Märkten auf 6 % in drei Jahren begrenzen, Indexmieten deckeln', '{204}', null, 2, 3, '{"mieter":{"wert":1,"begruendung":"Begrenzt Mieterhöhungen im laufenden Mietverhältnis."},"eigentuemer":{"wert":-1,"begruendung":"Begrenzt Mieterhöhungen im Bestand."}}'::jsonb, 'Begrenzt Erhöhungen in laufenden Mietverträgen spürbar, vor allem in angespannten Märkten; schafft keine neuen Wohnungen.', 'https://www.spd.de/fileadmin/Dokumente/Beschluesse/Programm/2025_SPD_Regierungsprogramm.pdf#page=21', null, 'gemischt', '2026-09-27', false, true, null, null),
  (2013, 2, 12, null, 'Sozialen Wohnungsbau stärken; Wohnungsgesellschaften und Genossenschaften über einen Deutschlandfonds mit Eigenkapital ausstatten', '{201,206}', null, 2, 2, null, 'Mehr Kapital für gemeinwohlorientierte Bauherren kann das Angebot günstiger Wohnungen erhöhen; erfordert erhebliche öffentliche Mittel.', 'https://www.spd.de/fileadmin/Dokumente/Beschluesse/Programm/2025_SPD_Regierungsprogramm.pdf#page=21', null, 'offen', '2026-09-27', false, true, null, null),
  (2014, 2, 12, null, 'Baukosten senken: Gebäudetyp E weiterentwickeln, serielles und modulares Bauen fördern, Bauverwaltung digitalisieren', '{203}', 6641, 2, 3, null, 'Verhindert weitere Kostensteigerungen durch Vorschriften und verkürzt Verfahren; bereits gestiegene Material-, Lohn- und Zinskosten bleiben. Wie viel Standards an den Baukosten ausmachen, ist umstritten.', 'https://www.spd.de/fileadmin/Dokumente/Beschluesse/Programm/2025_SPD_Regierungsprogramm.pdf#page=22', null, 'gemischt', '2026-09-27', false, true, null, null),
  (2015, 2, 12, null, 'Neue bundeseigene Wohnungsgesellschaft gründen', '{201}', null, 1, 2, null, 'Schafft zusätzliche Wohnungen, laut Programm vor allem für Beschäftigte des Bundes; die Wirkung auf den allgemeinen Markt ist begrenzt.', 'https://www.spd.de/fileadmin/Dokumente/Beschluesse/Programm/2025_SPD_Regierungsprogramm.pdf#page=22', null, 'offen', '2026-09-27', false, true, null, null),
  (2021, 2, 13, null, 'Mietpreisbremse verlängern, Ausnahmen abschaffen, auf Wohnungen älter als fünf Jahre anwenden und Schlupflöcher (möbliert, Ferienwohnung) schließen', '{202}', null, 2, 3, '{"mieter":{"wert":1,"begruendung":"Begrenzt die Miete bei Neuvermietung unmittelbar."},"eigentuemer":{"wert":-1,"begruendung":"Begrenzt mögliche Mieteinnahmen bei Neuvermietung."}}'::jsonb, 'Dämpft Mieten bei Neuvermietung in angespannten Märkten; schafft keine neuen Wohnungen.', 'https://cms.gruene.de/uploads/assets/20250318_Regierungsprogramm_DIGITAL_DINA5.pdf#page=69', null, 'gemischt', '2026-09-27', false, true, null, null),
  (2022, 2, 13, null, 'Mietenstopp in angespannten Wohnungsmärkten ermöglichen und Kappungsgrenzen senken', '{204}', 6639, 2, 2, '{"mieter":{"wert":1,"begruendung":"Verhindert Mieterhöhungen im laufenden Mietverhältnis."},"eigentuemer":{"wert":-1,"begruendung":"Schließt Mieterhöhungen im Bestand zeitweise aus."}}'::jsonb, 'Stoppt Erhöhungen in laufenden Mietverträgen in angespannten Märkten; schafft keine neuen Wohnungen und kann Instandhaltung und Modernisierung bremsen. Ein Mietenstopp wirft verfassungsrechtliche Fragen auf.', 'https://cms.gruene.de/uploads/assets/20250318_Regierungsprogramm_DIGITAL_DINA5.pdf#page=69', null, 'gemischt', '2026-09-27', false, true, null, null),
  (2023, 2, 13, null, 'Mehr Wohnraum im Bestand: Aufstockung, Umwandlung von Büros, Dachausbau; Baurecht vereinfachen, Verfahren digitalisieren, Standards zurückführen', '{201,203,205}', null, 2, 2, null, 'Nutzt vorhandene Gebäude und senkt Kosten durch einfachere Regeln; wie viele Wohnungen so entstehen, ist unsicher.', 'https://cms.gruene.de/uploads/assets/20250318_Regierungsprogramm_DIGITAL_DINA5.pdf#page=71', null, 'gemischt', '2026-09-30', false, true, null, null),
  (2024, 2, 13, null, 'Fördermittel für sozialen und gemeinnützigen Wohnungsbau erhöhen, Miet- und Belegungsbindungen unbefristet', '{201,206}', 6642, 2, 2, null, 'Schafft preisgebundene Wohnungen für Haushalte mit geringem Einkommen; erfordert erhebliche öffentliche Mittel, der Umfang ist nicht beziffert.', 'https://cms.gruene.de/uploads/assets/20250318_Regierungsprogramm_DIGITAL_DINA5.pdf#page=72', null, 'belegt', '2026-09-27', false, true, null, null),
  (2031, 2, 14, null, 'Steuerliche Abschreibungen im Wohnungsbau verbessern, Sonderabschreibung fortführen', '{201}', 6640, 2, 2, null, 'Steuerliche Anreize können Neubau anstoßen; kostet Steuereinnahmen, und ob die Wohnungen günstig vermietet werden, ist nicht gesichert. Frühere Sonderabschreibungen wirkten vor allem bei ohnehin geplanten Projekten.', 'https://www.fdp.de/sites/default/files/2024-12/fdp-wahlprogramm_2025.pdf#page=43', null, 'gemischt', '2026-09-27', false, true, null, null),
  (2032, 2, 14, null, 'Baukostenmoratorium, Bau-Auflagen auf Mindeststandards reduzieren, serielles Bauen mit bundesweiten Standards', '{203}', null, 2, 2, null, 'Setzt an Vorschriften als Kostentreiber an; Mindeststandards bei Gebäudeenergie sind teils durch EU-Recht vorgegeben.', 'https://www.fdp.de/sites/default/files/2024-12/fdp-wahlprogramm_2025.pdf#page=44', null, 'gemischt', '2026-09-27', false, true, null, null),
  (2033, 2, 14, null, 'Genehmigungsfiktion für Bauanträge, durchgehend digitale Planung, einfachere Ausweisung neuer Bauflächen', '{201}', null, 2, 2, null, 'Beschleunigt Verfahren und erweitert das Flächenangebot; Personalmangel in Bauämtern bleibt ein Engpass.', 'https://www.fdp.de/sites/default/files/2024-12/fdp-wahlprogramm_2025.pdf#page=44', null, 'offen', '2026-09-27', false, true, null, null),
  (2034, 2, 14, null, 'Mietpreisbremse auslaufen lassen, um Anreize für Neubau zu setzen', '{201}', 6637, 1, 3, '{"mieter":{"wert":-1,"begruendung":"Fällt die Begrenzung weg, können Neuvermietungsmieten in angespannten Märkten stärker steigen."},"eigentuemer":{"wert":1,"begruendung":"Mehr Spielraum bei der Miethöhe."}}'::jsonb, 'Soll Investitionen anregen; Neubauten sind von der Mietpreisbremse ohnehin ausgenommen, die Wirkung auf den Neubau ist daher gering. Studien finden keinen deutlichen Rückgang des Neubaus durch die Bremse.', 'https://www.fdp.de/sites/default/files/2024-12/fdp-wahlprogramm_2025.pdf#page=44', null, 'gemischt', '2026-09-27', false, true, null, null),
  (2041, 2, 15, null, 'Gebäudeenergiegesetz abschaffen und kostentreibende EU-Bauvorschriften ablehnen', '{203}', null, 1, 1, null, 'Senkt einzelne Anforderungen an Neubauten; das Gesetz setzt zum Teil EU-Recht um, eine Abschaffung wäre daher nur eingeschränkt möglich.', 'https://www.afd.de/wp-content/uploads/2025/02/AfD_Bundestagswahlprogramm2025_web.pdf#page=37', null, 'offen', '2026-09-27', false, true, null, null),
  (2042, 2, 15, null, 'Mehr Wohngeld und zusätzliches kommunales Wohngeld statt sozialem Wohnungsbau', '{202,206}', null, 1, 2, null, 'Entlastet Haushalte mit geringem Einkommen direkt; schafft keine zusätzlichen Wohnungen, der Verzicht auf sozialen Wohnungsbau verringert das Angebot günstiger Wohnungen.', 'https://www.afd.de/wp-content/uploads/2025/02/AfD_Bundestagswahlprogramm2025_web.pdf#page=38', null, 'belegt', '2026-09-30', false, true, null, null),
  (2043, 2, 15, null, 'Mietpreisbremse und Mietendeckel ablehnen, um Investitionshemmnisse abzubauen', '{201}', 6637, 1, 3, '{"mieter":{"wert":-1,"begruendung":"Fällt die Begrenzung weg, können Neuvermietungsmieten in angespannten Märkten stärker steigen."},"eigentuemer":{"wert":1,"begruendung":"Mehr Spielraum bei der Miethöhe."}}'::jsonb, 'Soll Investitionen anregen; Neubauten sind von der Mietpreisbremse ohnehin ausgenommen, die Wirkung auf den Neubau ist daher gering. Studien finden keinen deutlichen Rückgang des Neubaus durch die Bremse.', 'https://www.afd.de/wp-content/uploads/2025/02/AfD_Bundestagswahlprogramm2025_web.pdf#page=39', null, 'gemischt', '2026-09-27', false, true, null, null),
  (2051, 2, 16, null, 'Bundesweiter Mietendeckel; besonders hohe Mieten in angespannten Märkten absenken', '{202}', 6638, 2, 1, '{"mieter":{"wert":1,"begruendung":"Senkt oder begrenzt die Miete unmittelbar."},"eigentuemer":{"wert":-1,"begruendung":"Begrenzt oder senkt Mieteinnahmen."}}'::jsonb, 'Begrenzt Mieten direkt, auch bei Neuvermietung, schafft aber keine neuen Wohnungen; in Berlin sanken 2020/21 die regulierten Mieten, zugleich wurden weniger Wohnungen angeboten. Ob ein bundesweiter Deckel mit Absenkung verfassungsgemäß wäre, ist offen.', 'https://www.die-linke.de/fileadmin/user_upload/Wahlprogramm_Langfassung_Linke-BTW25_01.pdf#page=8', null, 'gemischt', '2026-09-28', false, true, null, null),
  (2052, 2, 16, null, 'Mieterhöhungen bundesweit für sechs Jahre ausschließen; Staffel- und Indexmieten verbieten', '{204}', null, 2, 1, '{"mieter":{"wert":1,"begruendung":"Verhindert Mieterhöhungen im laufenden Mietverhältnis."},"eigentuemer":{"wert":-1,"begruendung":"Schließt Mieterhöhungen im Bestand zeitweise aus."}}'::jsonb, 'Stoppt Erhöhungen in laufenden Mietverträgen vollständig; ein bundesweiter Stopp über sechs Jahre wirft erhebliche verfassungsrechtliche Fragen auf.', 'https://www.die-linke.de/fileadmin/user_upload/Wahlprogramm_Langfassung_Linke-BTW25_01.pdf#page=8', null, 'gemischt', '2026-09-28', false, true, null, null),
  (2053, 2, 16, null, '20 Milliarden Euro im Jahr für gemeinnützigen Wohnungsbau, Sozialbindung dauerhaft, Investitionen von der Schuldenbremse ausnehmen', '{201,206,205}', null, 2, 1, null, 'Würde das Angebot dauerhaft günstiger Wohnungen deutlich erhöhen; die Ausnahme von der Schuldenbremse erfordert eine Verfassungsänderung.', 'https://www.die-linke.de/fileadmin/user_upload/Wahlprogramm_Langfassung_Linke-BTW25_01.pdf#page=9', null, 'belegt', '2026-09-30', false, true, null, null),
  (2054, 2, 16, null, 'Wohnungsbestände von Konzernen mit mehr als 3.000 Wohnungen vergesellschaften', '{202}', null, 1, 1, null, 'Kann Mieten im übernommenen Bestand dämpfen, schafft aber keine neuen Wohnungen; Entschädigung unter Marktwert ist rechtlich umstritten und teuer.', 'https://www.die-linke.de/fileadmin/user_upload/Wahlprogramm_Langfassung_Linke-BTW25_01.pdf#page=9', null, 'offen', '2026-09-28', false, true, null, null),
  (2055, 2, 16, null, 'Leerstand erfassen und mit einer Abgabe von 10 Euro pro Quadratmeter belegen', '{201}', null, 1, 2, null, 'Kann leerstehende Wohnungen auf den Markt bringen; in angespannten Märkten ist der Leerstand gering, ein großer Teil liegt in schrumpfenden Regionen.', 'https://www.die-linke.de/fileadmin/user_upload/Wahlprogramm_Langfassung_Linke-BTW25_01.pdf#page=9', null, 'offen', '2026-09-28', false, true, null, null),
  (2056, 2, 16, null, 'Regulierungen beim Neubau überprüfen, soweit sie nur die Preise treiben', '{203}', null, 1, 3, null, 'Setzt an Vorschriften als Kostentreiber an, bleibt aber allgemein und nennt keine konkreten Regeln.', 'https://www.die-linke.de/fileadmin/user_upload/Wahlprogramm_Langfassung_Linke-BTW25_01.pdf#page=9', null, 'offen', '2026-09-28', false, true, null, null),
  (2061, 2, 17, null, 'Gemeinnützigen und kommunalen Wohnungsbau stärken: zinsvergünstigte Kredite, großes Wohnungsbauprogramm, dauerhafte Sozialbindung', '{201,206,205}', 6642, 2, 2, null, 'Schafft preisgebundene Wohnungen für Haushalte mit geringem Einkommen; erfordert erhebliche öffentliche Mittel, der Umfang ist nicht beziffert.', 'https://bsw-vg.de/wp-content/themes/bsw/assets/downloads/BSW%20Wahlprogramm%202025.pdf#page=28', null, 'belegt', '2026-09-30', false, true, null, null),
  (2062, 2, 17, null, 'Bundesweiter Mietendeckel statt Mietpreisbremse', '{202}', 6638, 2, 1, '{"mieter":{"wert":1,"begruendung":"Senkt oder begrenzt die Miete unmittelbar."},"eigentuemer":{"wert":-1,"begruendung":"Begrenzt oder senkt Mieteinnahmen."}}'::jsonb, 'Begrenzt Mieten direkt, auch bei Neuvermietung, schafft aber keine neuen Wohnungen; in Berlin sanken 2020/21 die regulierten Mieten, zugleich wurden weniger Wohnungen angeboten. Ob ein bundesweiter Deckel mit Absenkung verfassungsgemäß wäre, ist offen.', 'https://bsw-vg.de/wp-content/themes/bsw/assets/downloads/BSW%20Wahlprogramm%202025.pdf#page=28', null, 'gemischt', '2026-09-28', false, true, null, null),
  (2063, 2, 17, null, 'Mieten in Regionen mit knappem bezahlbarem Wohnraum bis Ende des Jahrzehnts einfrieren; Sanierungskosten tragen die Vermieter', '{204}', 6639, 2, 2, '{"mieter":{"wert":1,"begruendung":"Verhindert Mieterhöhungen im laufenden Mietverhältnis."},"eigentuemer":{"wert":-1,"begruendung":"Schließt Mieterhöhungen im Bestand zeitweise aus."}}'::jsonb, 'Stoppt Erhöhungen in laufenden Mietverträgen in angespannten Märkten; schafft keine neuen Wohnungen und kann Instandhaltung und Modernisierung bremsen. Ein Mietenstopp wirft verfassungsrechtliche Fragen auf.', 'https://bsw-vg.de/wp-content/themes/bsw/assets/downloads/BSW%20Wahlprogramm%202025.pdf#page=28', null, 'gemischt', '2026-09-28', false, true, null, null),
  (2064, 2, 17, null, 'Bauvorhaben beschleunigen: serielles Bauen vereinfachen, vereinfachtes Genehmigungsverfahren für sozialen Wohnungsbau, überzogene Bauvorschriften prüfen', '{201,203}', null, 2, 2, null, 'Setzt an Verfahrensdauer und Vorschriften an; wie stark die Kosten sinken, hängt von der Umsetzung in den Ländern ab.', 'https://bsw-vg.de/wp-content/themes/bsw/assets/downloads/BSW%20Wahlprogramm%202025.pdf#page=28', null, 'gemischt', '2026-09-28', false, true, null, null),
  (6643, 2, 13, null, 'Mietwucher leichter ahnden (§ 5 Wirtschaftsstrafgesetz), Indexmieten durch Obergrenzen begrenzen', '{202,204}', null, 1, 3, '{"mieter":{"wert":1,"begruendung":"Stärkt die Rechte von Mieterinnen und Mietern unmittelbar."}}'::jsonb, 'Erleichtert es, überhöhte Mieten zurückzufordern, und begrenzt Erhöhungen bei Indexmieten; wirkt nur für einen Teil der Verträge und schafft keine Wohnungen.', 'https://cms.gruene.de/uploads/assets/20250318_Regierungsprogramm_DIGITAL_DINA5.pdf#page=69', null, 'offen', '2026-09-30', false, true, null, null),
  (6644, 2, 15, null, 'Keine Zuweisung von Asylberechtigten und Asylbewerbern mehr in angespannte Wohnungsmärkte', '{205}', null, 1, 2, null, 'Verringert die Nachfrage in angespannten Märkten nur für eine kleine Gruppe und verlagert sie in andere Regionen; anerkannte Flüchtlinge dürfen nur befristet und zur Integration an einen Wohnort gebunden werden (§ 12a AufenthG).', 'https://www.afd.de/wp-content/uploads/2025/02/AfD_Bundestagswahlprogramm2025_web.pdf#page=111', null, 'offen', '2026-09-30', false, true, null, null),
  (6651, 2, 11, 'ST', 'Sozialen Wohnungsbau fördern, Wohnraumförderprogramme des Bundes weiter kofinanzieren', '{206}', 6645, 1, 3, null, 'Hält den Neubau geförderter Wohnungen aufrecht, bremst aber den Rückgang des Bestands nicht, solange mehr Wohnungen aus der Bindung fallen als neu gefördert werden.', 'https://www.cdulsa.de/sites/www.cdulsa.de/files/downloads/regierungsprogramm_ltw_web.pdf#page=65', null, 'belegt', '2026-09-30', false, true, null, null),
  (6652, 2, 12, 'ST', 'Sozialen Wohnungsbau stärken, Bundesmittel nutzen und kofinanzieren', '{206}', 6646, 2, 2, null, 'Mehr geförderte Neubauten wirken dem Rückgang des Bestands direkt entgegen; das Land muss dafür zusätzliche Haushaltsmittel bereitstellen, und die Wirkung hängt davon ab, dass Bauherren die Förderung annehmen.', 'https://spdsachsenanhalt.de/wp-content/uploads/sites/63/2026/03/SPD-Wahlprogramm-2026.pdf#page=43', null, 'belegt', '2026-09-30', false, true, null, null),
  (6653, 2, 13, 'ST', 'Sozialen Wohnungsbau und die Bundesmittel dafür in Sachsen-Anhalt nutzbar machen', '{206}', 6646, 2, 2, null, 'Mehr geförderte Neubauten wirken dem Rückgang des Bestands direkt entgegen; das Land muss dafür zusätzliche Haushaltsmittel bereitstellen, und die Wirkung hängt davon ab, dass Bauherren die Förderung annehmen.', 'https://www.gruene-lsa.de/wp-content/uploads/2026/05/Programm-zur-Landtagswahl-2026.pdf#page=91', null, 'belegt', '2026-09-30', false, true, null, null),
  (6654, 2, 15, 'ST', '1:1-Kofinanzierung der Bundesmittel für den sozialen Wohnungsbau wiederbeleben', '{206}', 6646, 2, 2, null, 'Mehr geförderte Neubauten wirken dem Rückgang des Bestands direkt entgegen; das Land muss dafür zusätzliche Haushaltsmittel bereitstellen, und die Wirkung hängt davon ab, dass Bauherren die Förderung annehmen.', 'https://afd-lsa.de/wp-content/uploads/2026/07/AfD_Sachsen-Anhalt_Regierungsprogramm_2026_230726-web.pdf#page=190', null, 'belegt', '2026-09-30', false, true, null, null),
  (6655, 2, 16, 'ST', 'Wohnungsbauförderung nur noch für unbefristet gebundenen sozialen Mietwohnungsbau', '{206}', 6647, 2, 3, null, 'Verhindert, dass künftig geförderte Wohnungen nach einigen Jahren aus der Bindung fallen; das Land kann das im eigenen Förderrecht regeln. Private Bauherren nehmen eine Förderung mit Dauerbindung womöglich seltener an.', 'https://www.dielinke-sachsen-anhalt.de/fileadmin/aaa_download_lsa/Parteitage/10._LPT_2._Tagung_VV_LTW_2026/Beschluesse/2026-03-19_Landtagswahlprogramm__final_.pdf#page=83', null, 'gemischt', '2026-09-30', false, true, null, null),
  (6656, 2, 16, 'ST', 'Landeswohnungsbaugesellschaft gründen, deren Wohnungen nicht aus der Sozialbindung fallen', '{206}', null, 2, 2, null, 'Eine eigene Gesellschaft kann dauerhaft gebundene Wohnungen bauen, wo andere nicht investieren; Aufbau und Eigenkapital kosten Zeit und Geld, und in vielen Regionen Sachsen-Anhalts fehlt eher Nachfrage als Angebot.', 'https://www.dielinke-sachsen-anhalt.de/fileadmin/aaa_download_lsa/Parteitage/10._LPT_2._Tagung_VV_LTW_2026/Beschluesse/2026-03-19_Landtagswahlprogramm__final_.pdf#page=84', null, 'offen', '2026-09-30', false, true, null, null),
  (6657, 2, 17, 'ST', 'Sozialen und gemeinnützigen Wohnungsbau deutlich ausweiten', '{206}', 6646, 2, 2, null, 'Mehr geförderte Neubauten wirken dem Rückgang des Bestands direkt entgegen; das Land muss dafür zusätzliche Haushaltsmittel bereitstellen, und die Wirkung hängt davon ab, dass Bauherren die Förderung annehmen.', 'https://st.bsw-vg.de/wp-content/uploads/2026/04/BSW_Landtagswahlprogramm_SachsenAnhalt.pdf#page=30', null, 'belegt', '2026-09-30', false, true, null, null),
  (6658, 2, 11, 'MV', 'Eigenes Landesprogramm zur Förderung des Mietwohnungsbaus, vor allem für kommunale und genossenschaftliche Wohnungsunternehmen', '{206}', null, 1, 3, null, 'Mehr geförderte Mietwohnungen kommunaler und genossenschaftlicher Unternehmen können günstige Wohnungen sichern; das Programm nennt aber weder Miet- noch Belegungsbindungen noch einen Umfang.', 'https://cdu-mv.de/wp-content/uploads/2026/06/Wahlprogramm-CDU-MV-2026.pdf#page=19', null, 'offen', '2026-09-30', false, true, null, null),
  (6659, 2, 12, 'MV', 'Landesförderprogramm für sozialen Wohnungsneubau fortführen', '{206}', 6645, 1, 3, null, 'Hält den Neubau geförderter Wohnungen aufrecht, bremst aber den Rückgang des Bestands nicht, solange mehr Wohnungen aus der Bindung fallen als neu gefördert werden.', 'https://spd-mv.de/uploads/bilderpool/2-Mecklenburg-Vorpommern/Wahlen-und-Kandidaturen/2026-Landtagswahlen/SPD_MV_Programm_2026.pdf#page=54', null, 'belegt', '2026-09-30', false, true, null, null),
  (6660, 2, 13, 'MV', 'Landesprogramm „Wohnungsbau Sozial“ aufstocken, höhere Zuschüsse für Sozialwohnungen', '{206}', 6646, 2, 2, null, 'Mehr geförderte Neubauten wirken dem Rückgang des Bestands direkt entgegen; das Land muss dafür zusätzliche Haushaltsmittel bereitstellen, und die Wirkung hängt davon ab, dass Bauherren die Förderung annehmen.', 'https://gruene-mv.de/?wpdmdl=33772#page=53', null, 'belegt', '2026-09-30', false, true, null, null),
  (6661, 2, 13, 'MV', 'Sozialbindung entfristen', '{206}', 6647, 2, 3, null, 'Verhindert, dass künftig geförderte Wohnungen nach einigen Jahren aus der Bindung fallen; das Land kann das im eigenen Förderrecht regeln. Private Bauherren nehmen eine Förderung mit Dauerbindung womöglich seltener an.', 'https://gruene-mv.de/?wpdmdl=33772#page=54', null, 'gemischt', '2026-09-30', false, true, null, null),
  (6662, 2, 13, 'MV', 'Höhere Quote für Sozialwohnungen bei Neubauten', '{206}', 6648, 2, 2, null, 'Sichert in neuen Quartieren mehr Sozialwohnungen ohne volle Landesförderung; eine sehr hohe Quote kann private Bauvorhaben unwirtschaftlich machen und den Neubau bremsen.', 'https://gruene-mv.de/?wpdmdl=33772#page=54', null, 'gemischt', '2026-09-30', false, true, null, null),
  (6663, 2, 16, 'MV', 'Förderprogramme für den sozialen Wohnungsbau reformieren und attraktiver machen', '{206}', 6646, 2, 2, null, 'Mehr geförderte Neubauten wirken dem Rückgang des Bestands direkt entgegen; das Land muss dafür zusätzliche Haushaltsmittel bereitstellen, und die Wirkung hängt davon ab, dass Bauherren die Förderung annehmen.', 'https://wahlprogramm26.die-linke-mv.de/wp-content/uploads/sites/77/2026/08/LINKE-MV_LTW26_Langwahlprogramm_A4_web.pdf#page=6', null, 'belegt', '2026-09-30', false, true, null, null),
  (6664, 2, 17, 'MV', 'Sozialen Wohnungsbau mit verlässlichen Landesprogrammen bedarfsgerecht ausbauen', '{206}', 6646, 2, 2, null, 'Mehr geförderte Neubauten wirken dem Rückgang des Bestands direkt entgegen; das Land muss dafür zusätzliche Haushaltsmittel bereitstellen, und die Wirkung hängt davon ab, dass Bauherren die Förderung annehmen.', 'https://mv.bsw-vg.de/wp-content/uploads/2026/04/Landeswahlprogramm-2026.pdf#page=21', null, 'belegt', '2026-09-30', false, true, null, null),
  (6665, 2, 11, 'BE', 'Wohnraumförderung fortführen (rund 5.000 neue Sozialwohnungen im Jahr, Wohnraumförderfonds)', '{206}', 6645, 1, 3, null, 'Hält den Neubau geförderter Wohnungen aufrecht, bremst aber den Rückgang des Bestands nicht, solange mehr Wohnungen aus der Bindung fallen als neu gefördert werden.', 'https://berlin-wird.de/image/uploads/data/regierungsprogramm2026_2031.pdf#page=29', null, 'belegt', '2026-09-30', false, true, null, null),
  (6666, 2, 11, 'BE', 'Einkommensprüfung in Sozialwohnungen mit Mietzuschlag, Einnahmen für neue Sozialwohnungen', '{206}', 6649, 1, 3, null, 'Lenkt Sozialwohnungen stärker zu Bedürftigen und bringt Geld für neue Förderung; schafft selbst kaum neue Wohnungen, der Verwaltungsaufwand ist hoch, und Besserverdienende ziehen aus, was die Durchmischung verringern kann.', 'https://berlin-wird.de/image/uploads/data/regierungsprogramm2026_2031.pdf#page=31', null, 'gemischt', '2026-09-30', false, true, null, null),
  (6667, 2, 12, 'BE', 'Quote für Sozialwohnungen im kooperativen Baulandmodell von 30 auf 50 Prozent erhöhen', '{206}', 6648, 2, 2, null, 'Sichert in neuen Quartieren mehr Sozialwohnungen ohne volle Landesförderung; eine sehr hohe Quote kann private Bauvorhaben unwirtschaftlich machen und den Neubau bremsen.', 'https://library.fes.de/pdf-files/bibliothek/ltw-programme/SPD_Berlin_Wahlprogramm_20260521-v3-4_7942063.pdf#page=18', null, 'gemischt', '2026-09-30', false, true, null, null),
  (6668, 2, 12, 'BE', 'Eigentümer ab 50 Wohnungen verpflichten, einen Anteil an Haushalte mit Wohnberechtigungsschein zu vermieten', '{206}', 6650, 2, 1, null, 'Würde den Bestand an Wohnungen für Haushalte mit geringem Einkommen schnell erweitern; ob ein Land das regeln darf, ist fraglich, denn das Mietrecht ist Bundessache (Bundesverfassungsgericht 2021 zum Berliner Mietendeckel).', 'https://library.fes.de/pdf-files/bibliothek/ltw-programme/SPD_Berlin_Wahlprogramm_20260521-v3-4_7942063.pdf#page=21', null, 'offen', '2026-09-30', false, true, null, null),
  (6669, 2, 13, 'BE', 'Quote für mietpreisgebundene Wohnungen in der kooperativen Baulandentwicklung auf 50 Prozent erhöhen', '{206}', 6648, 2, 2, null, 'Sichert in neuen Quartieren mehr Sozialwohnungen ohne volle Landesförderung; eine sehr hohe Quote kann private Bauvorhaben unwirtschaftlich machen und den Neubau bremsen.', 'https://gruene.berlin/fileadmin/BE/lv_berlin/files/Wahlprogramm_2026_Online.pdf#page=60', null, 'gemischt', '2026-09-30', false, true, null, null),
  (6670, 2, 14, 'BE', 'Fehlbelegungsabgabe am Marktpreis orientiert', '{206}', 6649, 1, 3, null, 'Lenkt Sozialwohnungen stärker zu Bedürftigen und bringt Geld für neue Förderung; schafft selbst kaum neue Wohnungen, der Verwaltungsaufwand ist hoch, und Besserverdienende ziehen aus, was die Durchmischung verringern kann.', 'https://www.fdp-berlin.de/sites/default/files/2026-07/Wahlprogramm_FDP%20Berlin_Abgeordnetenhauswahl%202026_FINAL.pdf#page=42', null, 'gemischt', '2026-09-30', false, true, null, null),
  (6671, 2, 15, 'BE', 'Fehlbelegungsabgabe wieder einführen', '{206}', 6649, 1, 3, null, 'Lenkt Sozialwohnungen stärker zu Bedürftigen und bringt Geld für neue Förderung; schafft selbst kaum neue Wohnungen, der Verwaltungsaufwand ist hoch, und Besserverdienende ziehen aus, was die Durchmischung verringern kann.', 'https://lichtenberg.afd.berlin/wp-content/uploads/2026/07/AfD-WK-Berlin-Wahlprogramm-Webversion.pdf#page=6', null, 'gemischt', '2026-09-30', false, true, null, null),
  (6672, 2, 16, 'BE', 'Bestände mit auslaufenden Bindungen ankaufen, Förderprogramm zur Verlängerung auslaufender Bindungen', '{206}', null, 2, 2, null, 'Setzt direkt am Auslaufen der Bindungen an; Ankäufe und Verlängerungen sind teuer und schaffen keine zusätzlichen Wohnungen.', 'https://dielinke.berlin/fileadmin/download/2026/Wahlprogramm_AGH_2026_Die_Linke_Berlin.pdf#page=33', null, 'gemischt', '2026-09-30', false, true, null, null),
  (6673, 2, 16, 'BE', 'Kooperative Baulandentwicklung: mindestens zwei Drittel mietpreis- und belegungsgebundene Wohnungen', '{206}', 6648, 2, 2, null, 'Sichert in neuen Quartieren mehr Sozialwohnungen ohne volle Landesförderung; eine sehr hohe Quote kann private Bauvorhaben unwirtschaftlich machen und den Neubau bremsen.', 'https://dielinke.berlin/fileadmin/download/2026/Wahlprogramm_AGH_2026_Die_Linke_Berlin.pdf#page=36', null, 'gemischt', '2026-09-30', false, true, null, null),
  (6674, 2, 16, 'BE', 'Sicher-Wohnen-Gesetz: große Vermieter müssen einen Teil frei werdender Wohnungen zu Sozialmieten vermieten', '{206}', 6650, 2, 1, null, 'Würde den Bestand an Wohnungen für Haushalte mit geringem Einkommen schnell erweitern; ob ein Land das regeln darf, ist fraglich, denn das Mietrecht ist Bundessache (Bundesverfassungsgericht 2021 zum Berliner Mietendeckel).', 'https://dielinke.berlin/fileadmin/download/2026/Wahlprogramm_AGH_2026_Die_Linke_Berlin.pdf#page=23', null, 'offen', '2026-09-30', false, true, null, null),
  (6675, 2, 17, 'BE', 'Mindestens 6.000 neue Sozialwohnungen pro Jahr', '{206}', 6646, 2, 2, null, 'Mehr geförderte Neubauten wirken dem Rückgang des Bestands direkt entgegen; das Land muss dafür zusätzliche Haushaltsmittel bereitstellen, und die Wirkung hängt davon ab, dass Bauherren die Förderung annehmen.', 'https://bsw.berlin/wp-content/uploads/Wahlprogramm-BSW-Berlin-AGH-Wahl-2026.pdf#page=7', null, 'belegt', '2026-09-30', false, true, null, null),
  (6676, 2, 17, 'BE', 'Öffentlich geförderte Wohnungen dauerhaft binden', '{206}', 6647, 2, 3, null, 'Verhindert, dass künftig geförderte Wohnungen nach einigen Jahren aus der Bindung fallen; das Land kann das im eigenen Förderrecht regeln. Private Bauherren nehmen eine Förderung mit Dauerbindung womöglich seltener an.', 'https://bsw.berlin/wp-content/uploads/Wahlprogramm-BSW-Berlin-AGH-Wahl-2026.pdf#page=7', null, 'gemischt', '2026-09-30', false, true, null, null),
  (7221, 2, 12, null, 'Kurzzeitvermietung in Ballungsgebieten auf ein Mindestmaß reduzieren', '{201,205}', 7232, 1, 2, null, 'Weniger Ferienwohnungen und Leerstand bringen Wohnungen zurück auf den Mietmarkt, vor allem in Großstädten; bundesweit ist der Anteil klein. Zweckentfremdungsverbote erlassen die Länder, der Bund kann den Rahmen setzen.', 'https://www.spd.de/fileadmin/Dokumente/Beschluesse/Programm/2025_SPD_Regierungsprogramm.pdf#page=20', null, 'gemischt', '2026-09-30', false, true, null, null),
  (7222, 2, 11, null, 'Ballungsräume entlasten: Verkehrswege und Nahverkehr ins Umland bedarfsgerecht ausbauen', '{205}', null, 1, 2, null, 'Bessere Verbindungen machen das Umland als Wohnort attraktiver und können die Nachfrage in den Großstädten dämpfen; wie stark, ist kaum untersucht, und der Ausbau dauert Jahre.', 'https://www.cdu.de/app/uploads/2025/01/km_btw_2025_wahlprogramm_langfassung_ansicht.pdf#page=77', null, 'offen', '2026-09-30', false, true, null, null),
  (7223, 2, 16, null, 'Wohngeld-Antrag stark vereinfachen, Anträge binnen drei Monaten bescheiden', '{202}', null, 1, 3, null, 'Entlastet Haushalte mit geringem Einkommen direkt, wenn mehr Berechtigte das Wohngeld tatsächlich erhalten; zusätzliche Wohnungen entstehen dadurch nicht.', 'https://www.die-linke.de/fileadmin/user_upload/Wahlprogramm_Langfassung_Linke-BTW25_01.pdf#page=8', null, 'gemischt', '2026-09-30', false, true, null, null),
  (7233, 2, 17, null, 'Umwandlung von Wohnungen in Ferienwohnungen und Leerstand strenger regulieren', '{201}', 7232, 1, 2, null, 'Weniger Ferienwohnungen und Leerstand bringen Wohnungen zurück auf den Mietmarkt, vor allem in Großstädten; bundesweit ist der Anteil klein. Zweckentfremdungsverbote erlassen die Länder, der Bund kann den Rahmen setzen.', 'https://bsw-vg.de/wp-content/themes/bsw/assets/downloads/BSW%20Wahlprogramm%202025.pdf#page=28', null, 'gemischt', '2026-09-30', false, true, null, null);

select setval(pg_get_serial_sequence('public.massnahmen', 'id'), (select max(id) from public.massnahmen));

